      "stem": "甲公司存貨採用定期盤存制，X5 年度財務報表報導之總資產$3,200,000 及當年度淨利$170,000。甲公司於 X6 年發現 X4 年底有一批買入價格為$46,000 起運點交貨之商品，在 X4 年已計入進貨，但因該商品於 X5 年 1 月 5 日方送抵公司倉庫，因此未將該商品計入 X4 年底之期末存貨金額。另外，甲公司於 X5 年底賣出成本為$20,000 之存貨，出售條件為目的地交貨，且控制於目的地才移轉，該批貨品於 X6 年 1 月 2 日送達買方倉庫；甲公司將此存貨相關之銷貨收入認列為 X6 年度銷貨，且未將此批存貨計入 X5 年底之期末存貨。試問甲公司 X5 年度正確的資產總額及淨利金額分別為何？",
