      "number": 22,
      "stem": "假設您持有一個包含大量證券的多角化投資組合(well-diversified portfolio)，並且單一指數模型 (single index mode)成立。若已知您的投資組合的σ 為 0.24，而 σM 為 0.18。請問：投資組合的 β 約為多少？",
