      "subject": "investment",
      "sourceId": "investment-05",
      "number": 26,
      "stem": "老王投資120,000 元購買 β 係數為 1.25 的甲證券，另投資80,000 元購買 β 係數為 0.80 的乙證券。請問：老王的投資組合之β 係數為多少？",
