      "year": 110,
      "session": 3,
      "subject": "investment",
      "sourceId": "investment-09",
      "number": 27,
      "stem": "當標的資產(underlying asset)市價高於選擇權的履約價格(striking price)時，請問：賣權(put option) 處於下列何種情況？",
