      "year": 110,
      "session": 3,
      "subject": "investment",
      "sourceId": "investment-09",
      "number": 28,
      "stem": "已知同一股票的一年期買權(call option)及一年期的賣權(put option)之履約價格(striking price)為 100 元，若無風險利率為5%，股票價格為103 元，賣出賣權(put sells)的價格為 7.50 元，請問：買權(call)的價格應該是多少？",
